import sys

def find_alphabet_order(names):
    # Create a graph where each node is a letter and there's a directed edge from u to v if u comes before v in some name
    graph = {chr(i): set() for i in range(ord('a'), ord('z') + 1)}

    # Build the graph
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            min_len = min(len(names[i]), len(names[j]))
            for k in range(min_len):
                if names[i][k] != names[j][k]:
                    graph[names[i][k]].add(names[j][k])
                    break
            else:
                if len(names[i]) > len(names[j]):
                    return "Impossible"

    # Topological sort to find a valid order of letters
    def topological_sort():
        visited = set()
        stack = []

        def dfs(node):
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    dfs(neighbor)
            stack.append(node)

        for node in graph:
            if node not in visited:
                dfs(node)

        return stack[::-1]

    order = topological_sort()

    # Check if we have a valid order for all letters
    if len(order) < 26:
        return "Impossible"

    # Create the new alphabet order
    new_alphabet = ''.join(order)

    # Verify the order
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
